/* boot-explorer.js — boot-screen asset contact sheet (M5.1b).
 *
 * Renders window.BOOT_DATA (generated by tools/extract_boot_assets.py —
 * no fetch(), so it works from file:// like the game itself): every
 * boot/loading asset from the cdn/ bundles (group 'cdn', with bundle →
 * pack → origin provenance) alongside the APK-side set (group 'apk'),
 * grouped per boot slot so the art for the M5.1c boot sequence can be
 * picked tile by tile.
 */
(function () {
    'use strict';

    var D = window.BOOT_DATA;
    if (!D || !D.files) {
        document.getElementById('grid').textContent =
            'No data — run tools/extract_boot_assets.py first.';
        return;
    }

    // ---------------------------------------------------------------- helpers
    function el(tag, cls, text) {
        var n = document.createElement(tag);
        if (cls) { n.className = cls; }
        if (text != null) { n.textContent = text; }
        return n;
    }
    function humanBytes(n) {
        if (n == null) { return '—'; }
        if (n < 1024) { return n + ' B'; }
        if (n < 1024 * 1024) { return (n / 1024).toFixed(1) + ' KB'; }
        return (n / 1024 / 1024).toFixed(2) + ' MB';
    }
    function base(p) { return p.split('/').pop(); }

    var TABS = [
        { id: 'all', label: 'All' },
        { id: 'splash', label: 'Splash' },
        { id: 'dlcsplash', label: 'DLC Splash' },
        { id: 'loading', label: 'Loading' },
        { id: 'error', label: 'Error' },
        { id: 'extras', label: 'Menu extras' },
        { id: 'audio', label: 'Audio' },
        { id: 'data', label: 'Anchors' }
    ];
    var GROUPS = [
        { id: 'all', label: 'Both sides' },
        { id: 'apk', label: 'APK side' },
        { id: 'cdn', label: 'CDN packs' },
        { id: 'dlc', label: 'DLC splashes' }
    ];
    var GROUP_TAG = { apk: 'APK', cdn: 'CDN', dlc: 'DLC' };
    var GROUP_RANK = { apk: 0, cdn: 1, dlc: 2 };
    var TIER_RANK = { iphone: 0, ipad: 1, retina: 2, ipad3: 3,
                      small: 0, 'medium-small': 1, medium: 2, large: 3,
                      android: 4 };

    var state = { tab: 'all', group: 'all', dlcSource: null, q: '',
                  selected: null };

    // ------------------------------------------------------------- filtering
    function visible(e) {
        if (state.tab !== 'all' && e.tab !== state.tab) { return false; }
        if (state.group !== 'all' && e.group !== state.group) { return false; }
        if (state.group === 'dlc' && state.dlcSource && e.dlc !== state.dlcSource) {
            return false;
        }
        if (!state.q) { return true; }
        if (!e._hay) {
            e._hay = (e.path + ' ' + (e.slot || '') + ' ' + (e.role || '') +
                      ' ' + (e.label || '') + ' ' + (e.pack || '') + ' ' +
                      (e.dlc || '') + ' ' +
                      (e.bundle || '') + ' ' + (e.origin || '') + ' ' +
                      (e.tier || '') + ' ' + (e.revision != null ? 'r' + e.revision : '') +
                      ' ' + (e.group || '')).toLowerCase();
        }
        return e._hay.indexOf(state.q) >= 0;
    }

    function shown() {
        return D.files.filter(visible);
    }

    // ---------------------------------------------------------------- header
    var countsEl = document.getElementById('counts');
    var tabsEl = document.getElementById('tabs');
    var gridEl = document.getElementById('grid');
    var detailEl = document.getElementById('detail');
    var crumbEl = document.getElementById('crumb');
    var searchEl = document.getElementById('search');
    var genEl = document.getElementById('gen-stamp');

    if (genEl && D.generated) {
        genEl.textContent = ' — boot manifest generated ' + D.generated + ' by ' + D.tool;
    }

    function paintCounts() {
        var n = shown().length;
        countsEl.textContent = n + ' of ' + D.files.length + ' assets';
    }

    function paintTabs() {
        tabsEl.textContent = '';
        TABS.forEach(function (t) {
            var n = D.files.filter(function (e) {
                return t.id === 'all' ? true : e.tab === t.id;
            }).length;
            if (!n && t.id !== 'all') { return; }
            var b = el('button', state.tab === t.id ? 'on' : '');
            b.appendChild(document.createTextNode(t.label));
            b.appendChild(el('span', 'n', String(n)));
            b.addEventListener('click', function () {
                state.tab = t.id;
                paintAll();
            });
            tabsEl.appendChild(b);
        });
    }

    // source-side chips (APK / CDN) live in the crumb strip
    function paintCrumb() {
        crumbEl.textContent = '';
        crumbEl.appendChild(el('span', 'crumb-label', 'Source:'));
        GROUPS.forEach(function (g) {
            var b = el('button', state.group === g.id ? 'on' : '', g.label);
            b.addEventListener('click', function () {
                state.group = g.id;
                state.dlcSource = null;
                paintAll();
            });
            crumbEl.appendChild(b);
        });
        if (state.group === 'dlc') {
            // one source button per DLC pack family that ships splash art
            var byName = {};
            D.files.forEach(function (e) {
                if (e.group === 'dlc') {
                    (byName[e.dlc] = byName[e.dlc] || []).push(e);
                }
            });
            var names = Object.keys(byName).sort();
            crumbEl.appendChild(el('span', 'crumb-label',
                'DLC source (' + names.length + '):'));
            var mkSrc = function (label, name) {
                var b = el('button',
                    'srcbtn ' + ((state.dlcSource || null) === name ? 'on' : ''),
                    label);
                b.dataset.dlc = name || '';
                b.addEventListener('click', function () {
                    state.dlcSource = name;
                    paintAll();
                });
                crumbEl.appendChild(b);
            };
            mkSrc('All packs', null);
            names.forEach(function (n) {
                mkSrc(n + ' (' + byName[n].length + ')', n);
            });
        }
        if (D.bundles && D.bundles.length) {
            crumbEl.appendChild(el('span', 'crumb-label',
                'CDN side streamed from ' + D.bundles.map(function (b) {
                    return b.bundle + ' (' + b.packs + ' packs)';
                }).join(', ')));
        }
    }

    // ------------------------------------------------------------------ grid
    function tileFor(e) {
        var t = el('div', 'tile bs-' + e.group +
                    (state.selected === e.path ? ' sel' : ''));
        t.dataset.path = e.path;
        var pic;
        if (e.type === 'image') {
            pic = el('div', 'tile-pic');
            var img = document.createElement('img');
            img.loading = 'lazy';
            img.decoding = 'async';
            img.src = 'assets/' + (e.thumb || e.path);
            img.alt = base(e.path);
            pic.appendChild(img);
        } else if (e.type === 'audio') {
            pic = el('div', 'tile-pic glyph' +
                     (e.kind === 'music' ? ' music' : ''),
                     e.kind === 'music' ? '♫' : '♪');
        } else {
            pic = el('div', 'tile-pic glyph', '≡');
        }
        t.appendChild(pic);
        t.appendChild(el('div', 'tile-label', base(e.path)));
        var bits = [];
        if (e.tier) { bits.push(e.tier); }
        if (e.revision != null) { bits.push('r' + e.revision); }
        if (e.w != null && e.h != null) { bits.push(e.w + '×' + e.h); }
        bits.push(humanBytes(e.bytes));
        t.appendChild(el('div', 'tile-sub', bits.join(' · ')));
        var tag = el('span', 'src-tag', GROUP_TAG[e.group] || e.group);
        pic.appendChild(tag);
        t.addEventListener('click', function () { select(e); });
        return t;
    }

    function paintGrid() {
        gridEl.textContent = '';
        var frag = document.createDocumentFragment();
        var list = shown();
        var lastKey = null;
        list.forEach(function (e) {
            var key = e.tab + '|' + e.role + '|' + e.slot;
            if (key !== lastKey) {
                lastKey = key;
                var peers = D.files.filter(function (f) {
                    return f.role === e.role && f.slot === e.slot;
                });
                var h = el('div', 'gridgroup');
                h.appendChild(el('span', 'gg-label', e.label || e.role));
                h.appendChild(el('span', 'gg-slot', e.slot));
                h.appendChild(el('span', 'gg-n', peers.length + ' copies'));
                frag.appendChild(h);
            }
            frag.appendChild(tileFor(e));
        });
        if (!list.length) {
            frag.appendChild(el('div', 'placeholder', 'Nothing matches.'));
        }
        gridEl.appendChild(frag);
    }

    // ---------------------------------------------------------------- detail
    function metaTable(rows) {
        var t = document.createElement('table');
        t.className = 'meta';
        rows.forEach(function (r) {
            var tr = document.createElement('tr');
            tr.appendChild(el('td', null, r[0]));
            tr.appendChild(el('td', 'val', String(r[1])));
            t.appendChild(tr);
        });
        return t;
    }

    function detailFor(e) {
        detailEl.textContent = '';
        var box = el('div');

        var head = el('div', 'd-head');
        head.appendChild(el('h2', null, base(e.path)));
        var badges = el('div');
        badges.appendChild(el('span',
                              'badge ' + (e.group === 'apk' ? 'star' : 'dlc'),
                              e.group === 'apk' ? 'APK side'
                              : e.group === 'dlc' ? 'DLC pack' : 'CDN pack'));
        if (e.label) { badges.appendChild(el('span', 'badge', e.label)); }
        head.appendChild(badges);
        box.appendChild(head);
        var bits = [];
        if (e.tier) { bits.push(e.tier); }
        if (e.revision != null) { bits.push('r' + e.revision); }
        if (e.w != null && e.h != null) { bits.push(e.w + '×' + e.h); }
        bits.push(humanBytes(e.bytes));
        box.appendChild(el('div', 'd-sub', bits.join(' · ')));

        if (e.type === 'image') {
            var bar = el('div', 'zoombar');
            var img = document.createElement('img');
            img.src = 'assets/' + e.path;
            img.alt = base(e.path);
            var scroll = el('div', 'pv-scroll fit');
            scroll.appendChild(img);
            var fitBtn = el('button', 'on', 'Fit');
            var fullBtn = el('button', null, '100%');
            function setZoom(fit) {
                scroll.className = 'pv-scroll ' + (fit ? 'fit' : '');
                if (!fit) { img.removeAttribute('style'); }
                fitBtn.className = fit ? 'on' : '';
                fullBtn.className = fit ? '' : 'on';
            }
            fitBtn.addEventListener('click', function () { setZoom(true); });
            fullBtn.addEventListener('click', function () { setZoom(false); });
            bar.appendChild(fitBtn);
            bar.appendChild(fullBtn);
            bar.appendChild(el('span', 'hint', 'scroll at 100% to pan'));
            box.appendChild(bar);
            box.appendChild(scroll);
        } else if (e.type === 'audio') {
            var player = el('div', 'player');
            var a = document.createElement('audio');
            a.controls = true;
            a.src = 'assets/' + e.path;
            player.appendChild(a);
            box.appendChild(player);
        } else if (e.type === 'data') {
            box.appendChild(el('pre', 'data-text', e.text || ''));
        }

        // sibling copies of the exact boot slot (any side, tier, revision)
        var peers = D.files.filter(function (f) {
            return f.role === e.role && f.slot === e.slot;
        });
        if (peers.length > 1) {
            var v = el('div', 'variants');
            v.appendChild(el('div', 'vlabel', 'Copies of this slot — ' + peers.length));
            var row = el('div', 'vrow');
            peers.sort(function (a, b) {
                var ga = GROUP_RANK[a.group], gb = GROUP_RANK[b.group];
                if (ga !== gb) { return ga - gb; }
                var ra = TIER_RANK[a.tier] != null ? TIER_RANK[a.tier] : 9;
                var rb = TIER_RANK[b.tier] != null ? TIER_RANK[b.tier] : 9;
                if (ra !== rb) { return ra - rb; }
                return (b.revision || 0) - (a.revision || 0);
            }).forEach(function (f) {
                var b = el('button', f.path === e.path ? 'on' : '',
                           (f.group === 'apk' ? 'APK ' : '') +
                           (f.tier || f.type) +
                           (f.revision != null ? ' · r' + f.revision : ''));
                b.addEventListener('click', function () { select(f); });
                row.appendChild(b);
            });
            v.appendChild(row);
            box.appendChild(v);
        }

        var rows = [
            ['Boot slot', e.slot],
            ['Role', (e.role || '') + (e.label ? ' — ' + e.label : '')],
            ['Side', e.group === 'cdn' ? 'CDN pack (extracted from cdn/ bundle)'
                                       : e.group === 'dlc'
                                         ? 'DLC pack (extracted CDN corpus)'
                                         : 'APK (extract_assets.py set)'],
            ['DLC source', e.dlc || '—'],
            ['Bundle', e.bundle || '—'],
            ['Pack', e.pack || '—'],
            ['Tier', e.tier || '—'],
            ['Revision', e.revision != null ? 'r' + e.revision : '—'],
            ['Original file', e.origin || '—'],
            ['Index version', e.indexVersion != null ? e.indexVersion : '—'],
            ['File size', humanBytes(e.bytes)]
        ];
        if (e.pngBytes != null) { rows.push(['PNG size', humanBytes(e.pngBytes)]); }
        if (e.duration_s != null) {
            rows.push(['Duration', e.duration_s + ' s']);
            rows.push(['Audio', (e.channels || '?') + ' ch · ' +
                       (e.sample_rate || '?') + ' Hz · IMA-ADPCM']);
        }
        box.appendChild(metaTable(rows));
        detailEl.appendChild(box);
    }

    function select(e) {
        state.selected = e.path;
        paintGrid();
        detailFor(e);
    }

    // ------------------------------------------------------------------ wire
    searchEl.addEventListener('input', function () {
        state.q = (searchEl.value || '').toLowerCase().trim();
        paintGrid();
        paintCounts();
    });

    function paintAll() {
        paintTabs();
        paintCrumb();
        paintGrid();
        paintCounts();
        if (state.selected) {
            var e = D.files.find(function (f) { return f.path === state.selected; });
            if (e) { detailFor(e); }
        }
    }

    paintAll();
})();
